def transform(grid):
 out=[r[:] for r in grid]
 pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
 top=min(r for r,c in pts); bottom=max(r for r,c in pts)
 trunk=next(c for r,c in pts if r==top)
 for r in range(top,bottom+1):
  if out[r][trunk]==0: out[r][trunk]=3
 for r,c in pts:
  for j in range(min(c,trunk),max(c,trunk)+1):
   if out[r][j]==0: out[r][j]=3
 return out
